import React from 'react'
import Masonry,{ResponsiveMasonry}  from 'react-responsive-masonry';
import galleryImages from './galleryImage';
import '../styles/home.css'
const MyGalllery = () => {
  return (
    <ResponsiveMasonry columnsCountBreakPoints={{350:1,768:3,900:4}}>
        <Masonry gutter='1rem'>
            {
                galleryImages.map((item,index) =>(
                    <img className="masonry__img" src={item} key={index} alt="" style={{'width':'100%','display':'block','borderRadius':'10px'}} />
                ))
            }
        </Masonry>

    </ResponsiveMasonry>
  )
}

export default MyGalllery
